const fs = require('fs');
const path = require('path');

const ENDPOINT = 'http://127.0.0.1:65162/status';
const OUT_DIR = path.join(__dirname, 'results');
const OUT_FILE = path.join(OUT_DIR, 'status.json');

async function main() {
  const res = await fetch(ENDPOINT);
  const status = res.status;

  fs.mkdirSync(OUT_DIR, { recursive: true });
  fs.writeFileSync(OUT_FILE, JSON.stringify({ status }, null, 2) + '\n');

  console.log(`status=${status} written to ${OUT_FILE}`);
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});

